import{_ as o,o as e,c as a,a2 as r}from"./chunks/framework.Crpw6aS5.js";const n=JSON.parse('{"title":"1964年 · 稳健主义的哲学宣言","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1964年.md","filePath":"05_quotes/by-year/1964年.md"}'),u={name:"05_quotes/by-year/1964年.md"};function l(q,t,c,s,_,p){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="_1964年-·-稳健主义的哲学宣言" tabindex="-1">1964年 · 稳健主义的哲学宣言 <a class="header-anchor" href="#_1964年-·-稳健主义的哲学宣言" aria-label="Permalink to &quot;1964年 · 稳健主义的哲学宣言&quot;">​</a></h1><blockquote><p>&quot;真正稳健的行为源于合理假设、准确事实、严谨推理。这些特质可能导向传统做法，也可能多次导向非传统。&quot;——巴菲特（34岁）</p></blockquote><p>本页收录1964年致股东信中的经典语录。巴菲特在这一年发出了最强的&quot;稳健主义&quot;宣言：区分&quot;传统&quot;与&quot;稳健&quot;是错误的，稳健只能通过独立思考和理性分析实现；并以曼哈顿印第安人卖出整个岛屿的故事，再次论证了复利的惊人力量。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>&quot;真正稳健的行为源于合理假设、准确事实、严谨推理。这些特质可能导向传统做法，也可能多次导向非传统。&quot;</p></blockquote><blockquote><p>&quot;我们不会因重要人物、发声者或多数人认同而安心，也不会因他们反对而不安。民意调查无法替代思考。&quot;</p></blockquote><blockquote><p>&quot;传统或非常规本身，都不代表稳健。&quot;</p></blockquote><blockquote><p>&quot;我向合伙人承诺：正如我认为当前业绩对比有意义，未来无论结果如何，我都会坚持对比。&quot;</p></blockquote><blockquote><p>&quot;我认为，评估过往策略稳健性的合理方式之一，是研究<strong>下跌市业绩</strong>。&quot;</p></blockquote><blockquote><p>&quot;买入环节占这项业务的90%。&quot;</p></blockquote><blockquote><p>&quot;我认为，曼哈顿印第安人只需实现6.5%的年化收益率，就能完胜米纽伊特。按6.5%计算，24美元338年后将变为421.057728亿美元。&quot;</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1964年道指上涨18.7%，合伙企业整体收益27.8%（有限合伙人22.3%），为1959年以来最低超额收益。巴菲特坦然接受，并再次强调：牛市跑输是正常现象，未来必有跑输道指的年份。伯克希尔·哈撒韦已纳入控股类持仓，为未来的历史性转折埋下伏笔。合伙企业净资产已达4300万美元。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><p><a href="/01_letters/1964年/翻译.html">01_letters/1964年/翻译</a> · <a href="/01_letters/1964年/核心总结.html">01_letters/1964年/核心总结</a> · <a href="/01_letters/1964年/思维导图.html">01_letters/1964年/思维导图</a></p>',18)])])}const b=o(u,[["render",l]]);export{n as __pageData,b as default};
